package io.github.some_example_name;
import io.github.some_example_name.database.*;import io.github.some_example_name.model.*;import java.util.*;
public final class DraftClass2001RegressionTest{public static void main(String[]a){require(DraftClassRepository.hasHistoricalClass(2001),"not registered");List<Player>ps=DraftClassRepository.getClassForYear(2001);require(ps.size()==60,"Expected 60");Set<String>old=new HashSet<>();for(int y=1970;y<=2000;y++)for(Player p:DraftClassRepository.getClassForYear(y))old.add(n(p.getName()));Map<String,Player>m=new HashMap<>();for(Player p:ps){require(p.getAge()==18,"age "+p.getName());require(!old.contains(n(p.getName())),"Repeated "+p.getName());require(m.put(p.getName(),p)==null,"Duplicate "+p.getName());}expect(m,"Philipp Lahm",Position.RB,54,73,78,87,78,98);expect(m,"Dani Alves",Position.RB,64,74,71,91,83,98);expect(m,"Carlos Diogo",Position.RB,52,64,68,90,66,91);System.out.println("Draft class 2001: 60 unique eligible prospects, attributes, positions and balanced potential OK.");}private static String n(String s){return s.toLowerCase(Locale.ROOT);}private static void expect(Map<String,Player>m,String n,Position q,int a,int p,int d,int f,int dr,int originalPot){Player x=m.get(n);require(x!=null&&x.getPrimaryPosition()==q&&x.getPotential()<=originalPot&&x.getTechnicalAttributes().getAtaque()==a&&x.getTechnicalAttributes().getPasse()==p&&x.getTechnicalAttributes().getDefesa()==d&&x.getTechnicalAttributes().getFisico()==f&&x.getTechnicalAttributes().getDrible()==dr,"Bad "+n);}private static void require(boolean b,String s){if(!b)throw new AssertionError(s);}}
